// DeleteUniqueIndexCache 删除索引存在的缓存
func (a *ActivityRepo) DeleteIndexCache(ctx context.Context, data ...*ai_boilerplate_model.Activity) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, a.cache.Key(CacheActivityByConditionPrefix))
	keys = append(keys, a.cache.Key(CacheActivityUnscopedByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[a.cache.Key(CacheActivityByIDPrefix, item.ID)] = struct{}{}
			KeyMap[a.cache.Key(CacheActivityUnscopedByIDPrefix, item.ID)] = struct{}{}
			KeyMap[a.cache.Key(CacheActivityBySortPrefix, item.Sort)] = struct{}{}
			KeyMap[a.cache.Key(CacheActivityUnscopedBySortPrefix, item.Sort)] = struct{}{}
			KeyMap[a.cache.Key(CacheActivityByStatusPrefix, item.Status)] = struct{}{}
			KeyMap[a.cache.Key(CacheActivityUnscopedByStatusPrefix, item.Status)] = struct{}{}
			KeyMap[a.cache.Key(CacheActivityByTenantIDPrefix, item.TenantID)] = struct{}{}
			KeyMap[a.cache.Key(CacheActivityUnscopedByTenantIDPrefix, item.TenantID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := a.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
